// Role catalog from GET /role of every enabled role, then the task itself.
const cards = [];
for (const role of ($env.AI_ROLES || '').split(',').map(s => s.trim()).filter(Boolean)) {
  try {
    cards.push(await this.helpers.httpRequest({ url: `http://role-${role}:9000/role`, json: true, timeout: 5000 }));
  } catch (e) {
    console.log(`role ${role} unavailable`, String(e.message || e));
  }
}
const form = $input.first().json;
return [
  { json: { event: { type: 'roles', cards } } },
  { json: { event: { type: 'task.create', title: form['Заголовок'], text: form['Описание'], refs: String(form['Ссылки'] || '').split('\n') } } },
];
